 "content": "def transform(grid):
    """Extend diagonal runs of repeated foreground colors away from the pattern."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    cr = sum(r for r, c in pts) / len(pts)
    cc = sum(c for r, c in pts) / len(pts)
    out = [row[:] for row in grid]
    for color in set(grid[r][c] for r, c in pts):
        cells = {(r, c) for r, c in pts if grid[r][c] == color}
        for r, c in list(cells):
            for dr, dc in ((1, 1), (1, -1)):
                q = (r + dr, c + dc)
                if q not in cells:
                    continue
                # Continue from whichever member of this diagonal pair lies farther
                # from the overall motif's center.
                d1 = (r - cr) ** 2 + (c - cc) ** 2
                d2 = (q[0] - cr) ** 2 + (q[1] - cc) ** 2
                if d1 >= d2:
                    sr, sc, step_r, step_c = r, c, -dr, -dc
                else:
                    sr, sc, step_r, step_c = q[0], q[1], dr, dc
                rr, col = sr + step_r, sc + step_c
                while 0 <= rr < h and 0 <= col < w:
                    if out[rr][col] == bg:
                        out[rr][col] = color
                    rr += step_r
                    col += step_c
    return out
